    public static AppLocalizedText GetText(string? languageId)
    {
        return !string.IsNullOrWhiteSpace(languageId) && TextByLanguageId.Value.TryGetValue(languageId, out var text)
            ? text
            : TextByLanguageId.Value[InterfaceLanguageOptions.EnglishId];
    }

    public static SettingsLocalizedText GetSettingsText(string? languageId) => GetText(languageId).Settings;

    public static LocalizedDisplayText GetTopicDisplayText(string? languageId, string canonicalTitle, string canonicalDescription)
    {
        var text = GetText(languageId);
        return text.TopicDisplayTextByTitle.TryGetValue(canonicalTitle, out var displayText)
            ? displayText
            : new LocalizedDisplayText(canonicalTitle, canonicalDescription);
    }

    public static LocalizedDisplayText GetSubtopicDisplayText(string? languageId, string canonicalTitle, string canonicalDescription)
    {
        var text = GetText(languageId);
        return text.SubtopicDisplayTextByTitle.TryGetValue(canonicalTitle, out var displayText)
            ? displayText
            : new LocalizedDisplayText(canonicalTitle, canonicalDescription);
    }

